  "onboarding.OnboardingTour.step_welcome_title": "Estimate Masterclass",
  "onboarding.OnboardingTour.step_welcome_content": "Welcome! This walkthrough will show you how to leverage the full power of our estimation engine. Ready to scale your speed and accuracy?",
  "onboarding.OnboardingTour.step_dashboard_overview_title": "Business Health",
  "onboarding.OnboardingTour.step_dashboard_overview_content": "Monitor your pipeline value, active production, and pending tasks from this command center.",
  "onboarding.OnboardingTour.step_calendar_overview_title": "Schedule & Dispatch",
  "onboarding.OnboardingTour.step_calendar_overview_content": "Drag-and-drop sales appointments and production jobs. Switch between Month, Week, and Day views to manage your team's time.",
  "onboarding.OnboardingTour.step_leads_overview_title": "Lead Pipeline",
  "onboarding.OnboardingTour.step_leads_overview_content": "Track potential customers from initial contact to booking. Drag cards to update status and convert leads into contacts and estimates.",
  "onboarding.OnboardingTour.step_contacts_overview_title": "Client Database",
  "onboarding.OnboardingTour.step_contacts_overview_content": "Manage relationships, view interaction history, and track lifetime value for every client.",
  "onboarding.OnboardingTour.step_estimates_overview_title": "Estimation Engine",
  "onboarding.OnboardingTour.step_estimates_overview_content": "This is the heart of the platform. We use high-fidelity production rates to ensure you never under-bid a project again.",
  "onboarding.OnboardingTour.step_est_create_title": "Starting a Project",
  "onboarding.OnboardingTour.step_est_create_content": "Start from a clean slate or choose from your pre-designed templates to fill a 10-room estimate in seconds.",
  "onboarding.OnboardingTour.step_est_client_title": "Data Reconciliation",
  "onboarding.OnboardingTour.step_est_client_content": "Associate customers with specific properties. Perfect for property managers or homeowners with multiple sites.",
  "onboarding.OnboardingTour.step_est_paint_title": "The Paint Card",
  "onboarding.OnboardingTour.step_est_paint_content": "Define your products globally for the project here. Any changes here sync instantly across all areas.",
  "onboarding.OnboardingTour.step_est_scope_title": "Dynamic Areas",
  "onboarding.OnboardingTour.step_est_scope_content": "Input L x W x H to auto-calculate all surfaces. Our math engine handles the \"unfolded\" surface area of complex architectural details.",
  "onboarding.OnboardingTour.step_est_add_item_title": "Injecting Rates",
  "onboarding.OnboardingTour.step_est_add_item_content": "Click \"Add Line Item\" inside an area to search your production rate library. It pulls in your specific efficiency speeds automatically.",
  "onboarding.OnboardingTour.step_est_misc_items_title": "Priced & Descriptive Items",
  "onboarding.OnboardingTour.step_est_misc_items_content": "Use this button to add miscellaneous items. \"Priced Items\" are for flat fees (like wallpaper removal), while \"Descriptive Items\" are for project terms or scope exclusions.",
  "onboarding.OnboardingTour.step_est_materials_title": "Material Intelligence",
  "onboarding.OnboardingTour.step_est_materials_content": "The engine automatically determines exactly how many gallon containers you need, optimized for cost and waste.",
  "onboarding.OnboardingTour.step_est_labor_summary_title": "Operational Vision",
  "onboarding.OnboardingTour.step_est_labor_summary_content": "Review total production hours by area. This gives your crew a precise target and helps you schedule production accurately.",
  "onboarding.OnboardingTour.step_est_finalize_title": "Financial Calibration",
  "onboarding.OnboardingTour.step_est_finalize_content": "Toggle between Hourly or OpEx pricing. We calculate your \"Fully Burdened\" labor cost to protect your net profit margin.",
  "onboarding.OnboardingTour.step_jobs_overview_title": "Active Operations",
  "onboarding.OnboardingTour.step_jobs_overview_content": "Once a bid is sold, it moves here for production. Track your crews and project milestones in real-time.",
  "onboarding.OnboardingTour.step_job_header_title": "Job Dashboard",
  "onboarding.OnboardingTour.step_job_header_content": "Manage status, access the work order, or launch a marketing campaign from the main header.",
  "onboarding.OnboardingTour.step_job_progress_title": "Milestone Tracker",
  "onboarding.OnboardingTour.step_job_progress_content": "Visualize the project lifecycle from \"Confirmed\" to \"Completed\". Click any stage to update the job status instantly.",
  "onboarding.OnboardingTour.step_job_financials_title": "Job Financials",
  "onboarding.OnboardingTour.step_job_financials_content": "Track total contract value, payments received, and outstanding balance in real-time.",
  "onboarding.OnboardingTour.step_workorders_overview_title": "Work Orders",
  "onboarding.OnboardingTour.step_workorders_overview_content": "Digital work orders provide crews with clear instructions, site access info, and task lists without revealing pricing.",
  "onboarding.OnboardingTour.step_wo_header_title": "Work Order Details",
  "onboarding.OnboardingTour.step_wo_header_content": "Manage schedule, crew assignment, and site access codes. Crews can view this on their mobile devices.",
  "onboarding.OnboardingTour.step_wo_tasks_title": "Field Access",
  "onboarding.OnboardingTour.step_wo_tasks_content": "Crews can view work orders, site photos, and specific instructions without seeing any of your pricing data.",
  "onboarding.OnboardingTour.step_invoices_overview_title": "Invoicing",
  "onboarding.OnboardingTour.step_invoices_overview_content": "Generate professional invoices, track payments, and manage outstanding balances.",
  "onboarding.OnboardingTour.step_presentations_overview_title": "Artisan Proposals",
  "onboarding.OnboardingTour.step_presentations_overview_content": "Don’t just send a PDF. Send a stunning, interactive web experience that sells your story and expertise.",
  "onboarding.OnboardingTour.step_pres_canvas_title": "Design Blocks",
  "onboarding.OnboardingTour.step_pres_canvas_content": "Drag design blocks onto the page. Edit text, swap photos, and brand the entire experience to your company.",
  "onboarding.OnboardingTour.step_settings_overview_title": "The Brain",
